/**
 * Peta status Keterlambatan → warna badge, plus format tanggal untuk kartu.
 *
 * Nama status mengikuti state Workflow "Persetujuan Keterlambatan" persis, dan
 * warnanya disamakan dengan indikator di desk supaya orang yang bolak-balik
 * antara portal dan desk melihat isyarat yang sama:
 *   Belum Diisi amber  ·  Menunggu Approval Ketua oranye  ·  Dimaafkan hijau
 *   Tidak Dimaafkan merah  ·  Kedaluwarsa & Tidak Diputuskan abu
 *
 * Kedaluwarsa dan Tidak Diputuskan sengaja seragam abu: keduanya sama-sama
 * berakhir tanpa dimaafkan, dan bedanya (siapa yang lalai) sudah terbaca dari
 * nama statusnya sendiri.
 */

const STATUS_BADGE = {
	'Belum Diisi': 'bg-ui-surface-amber-100 text-ui-ink-amber-700',
	'Menunggu Approval Atasan': 'bg-ui-surface-orange-100 text-ui-ink-orange-700',
	'Menunggu Approval Ketua': 'bg-ui-surface-orange-100 text-ui-ink-orange-700',
	Dimaafkan: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	'Tidak Dimaafkan': 'bg-ui-surface-red-100 text-ui-ink-red-700',
	Kedaluwarsa: 'bg-ui-surface-gray-200 text-ui-ink-gray-600',
	'Tidak Diputuskan': 'bg-ui-surface-gray-200 text-ui-ink-gray-600',
}

export function statusBadge(s) {
	return STATUS_BADGE[s] || 'bg-ui-surface-gray-200 text-ui-ink-gray-700'
}

/**
 * Warna garis kiri tiap baris Riwayat, mengikuti warna status yang dihasilkan
 * aksi itu. Baris riwayat hanya menyimpan nama aksi (lihat `AKSI` di
 * keterlambatan.py / kepulangan_cepat.py), tetapi tiap aksi berasal dari tepat
 * satu kelompok warna status, jadi cukup dipetakan dari namanya.
 */
const AKSI_GARIS = {
	'Dicatat sistem': 'border-ui-line-amber-500', // → Belum Diisi
	Diajukan: 'border-ui-line-orange-500', // → Menunggu Approval Atasan/Ketua
	'Diajukan ulang': 'border-ui-line-orange-500',
	Dimaafkan: 'border-ui-line-green-500',
	'Tidak Dimaafkan': 'border-ui-line-red-500',
	Kedaluwarsa: 'border-ui-line-gray-400',
	'Tidak Diputuskan': 'border-ui-line-gray-400',
}

export function garisRiwayat(aksi) {
	return AKSI_GARIS[aksi] || 'border-ui-line-gray-200'
}

const BULAN = [
	'Januari',
	'Februari',
	'Maret',
	'April',
	'Mei',
	'Juni',
	'Juli',
	'Agustus',
	'September',
	'Oktober',
	'November',
	'Desember',
]

const HARI = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu']

function urai(iso) {
	if (!iso) return null
	// Dipotong manual, bukan lewat `new Date(iso)`: string tanggal Frappe tanpa
	// zona waktu ditafsirkan sebagai UTC oleh sebagian browser, dan tanggalnya
	// bisa mundur sehari di zona WIB.
	const [y, m, d] = String(iso).slice(0, 10).split('-').map(Number)
	if (!y || !m || !d) return null
	return new Date(y, m - 1, d)
}

/** "Jumat, 22 Agustus" — tahun disembunyikan bila masih tahun berjalan. */
export function tanggalPanjang(iso) {
	const t = urai(iso)
	if (!t) return '—'
	const tahun = t.getFullYear() === new Date().getFullYear() ? '' : ` ${t.getFullYear()}`
	return `${HARI[t.getDay()]}, ${t.getDate()} ${BULAN[t.getMonth()]}${tahun}`
}

/** "22 Agu 2026" — bentuk ringkas untuk baris sekunder. */
export function tanggalRingkas(iso) {
	const t = urai(iso)
	if (!t) return '—'
	return `${t.getDate()} ${BULAN[t.getMonth()].slice(0, 3)} ${t.getFullYear()}`
}

/** "09:17" dari sebuah datetime Frappe. */
export function jam(iso) {
	if (!iso) return '—'
	return String(iso).slice(11, 16) || '—'
}

/** "22 Agu 2026 14:12" untuk baris riwayat. */
export function waktuRingkas(iso) {
	if (!iso) return '—'
	return `${tanggalRingkas(iso)} ${jam(iso)}`
}

/** "7 menit" / "1 jam 43 menit" — angka mentah sulit dibaca begitu melewati sejam. */
export function durasiMenit(menit) {
	const n = Number(menit) || 0
	if (n < 60) return `${n} menit`
	const jamPenuh = Math.floor(n / 60)
	const sisa = n % 60
	return sisa ? `${jamPenuh} jam ${sisa} menit` : `${jamPenuh} jam`
}
